#include <bits/stdc++.h>
#define int long long
using namespace std;
int h[300 + 9];//石头高度数组
signed main()
{
    int n;
    cin >> n;
    for (int i = 1; i <= n; i ++)
    {
        cin >> h[i];
    }
    sort(h + 1, h + n + 1);//按从低到高排序
    int lt = 1, rt = n, t = 0, now = 0;//l, r为下一个要跳石头的id，now为当前所在石头的id
    for (int i = 1; i <= n; i ++)
    {
        if (i % 2 != 0)//奇数次跳最高的石头
        {
            t += (now - h[rt]) * (now - h[rt]);//计算体力值
            now = h[rt];
            rt --;//最高的石头被跳过了
        }
        else//偶数次跳最低的石头
        {
            t += (now - h[lt]) * (now - h[lt]);//计算体力值
            now = h[lt];
            lt ++;//最低的石头被跳过了
        }
    }
    cout << t;
    return 0;
}

