#include <bits/stdc++.h>
using namespace std;
int a[20000 + 9], b[20000 + 9];
int main()
{
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i ++)
    {
        cin >> a[i];
    }
    for (int i = 1; i <= m; i ++)
    {
        cin >> b[i];
    }
    sort(a + 1, a + n + 1);//骑士按从小到大排序
    sort(b + 1, b + m + 1);//龙头按从小到大排序
    if (n > m)//骑士无法砍掉所有龙头
    {
        cout << "you died!";
        return 0;
    }
    int pos = 1, sum = 0;//从第一个骑士开始
    for (int i = 1; i <= n; i ++)
    {
        while (pos <= m && b[pos] < a[i])//去找能砍掉第i个龙头的骑士
        {
            pos ++;
        }
        if (pos == m + 1)//最大的骑士无法砍掉第i个龙头
        {
            cout << "you died!";
            return 0;
        }
        else
        {
            sum += b[pos];//计算价钱
            pos ++;
        }
    }
    cout << sum;
    return 0;
}

#include <bits/stdc++.h>
#define input(i) cin >> i;
#define print(i) cout << i << " ";
struct node
{
    int x, y;
}a[100000 + 9];
bool cmp(node a, node b)
{
    return a.y < b.y;//结构体排序
}
using namespace std;
int main()
{
    int n;
    input(n);
    for (int i = 1; i <= n; i ++)
    {
        input(a[i].x);//奶牛的数量
        input(a[i].y);//奶牛的产奶量
    }
    sort(a + 1, a + n + 1, cmp);
    int l = 1, r = n, ans = 0;//左右指针，时间
    while (l <= r)
    {
        if (a[l].x == a[r].x)//左边的数量和右边相同，全部匹配
        {
            ans = max(ans, a[l].y + a[r].y);//计算产奶量总和
            l ++;
            r --;
        }
        if (a[l].x < a[r].x)//左边较少，右边较多
        {
            ans = max(ans, a[l].y + a[r].y);//计算产奶量总和
            a[r].x -= a[l].x;//右边匹配了左边的数量
            l ++;//右边剩下的奶牛还能用
        }
        if (a[l].x > a[r].x)//左边较多，右边较少
        {
            ans = max(ans, a[l].y + a[r].y);//计算产奶量总和
            a[l]. x -= a[r].x;//左边匹配了右边的数量
            r --;//左边剩下的奶牛还能用
        }
    }
    print(ans);
    return 0;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;
int n, m;
string a[1000 + 9], b[100 + 9];
string p(string s)
{
    for (int i = 0; i < s.size(); i ++)
    {
        if (s[i] >= 'A' && s[i] <= 'Z')//是大写字母
        {
            s[i] += 32;//ASCII码值+32
        }
    }
    return s;
}
int work(string s)
{
    int ans = 0;符合条件的能量字符串个数
    for (int k = 1; k <= m; k ++)
    {
        int u1 = 0, u2 = 0, sum = 0;
        while (u1 < s.size())//枚举奶牛的名字字符
        {
            if (s[u1] == b[k][u2])//找到一个相同的
            {
                u1 ++;
                u2 ++;
                sum ++;//相同的字符+1
            }
            else
            {
                u1 ++;//换下一个字符
            }
        }
        if (sum == b[k].size())//当前能量字符串的所有字符都在奶牛名字中按顺序出现
        {
            ans ++;
        }
    }
    return ans;//返回答案
}
signed main()
{
    cin >> n >> m;
    for (int i = 1; i <= n; i ++)
    {
        cin >> a[i];
        a[i] = p(a[i]);//把奶牛的名字转成小写
    }
    for (int i = 1; i <= m; i ++)
    {
        cin >> b[i];
        b[i] = p(b[i]);//把能量字符串转成小写
    }
    for (int i = 1; i <= n; i ++)
    {
        cout << work(a[i]) << "\n";
    }
    return 0;
}

#include<bits/stdc++.h>
#define int long long
using namespace std;
int n, cnt = 1;
map <int, int> ma, h;
int p[5] = {0, 1, 1, 1, 1};//初始的数
int a[5] = {0, 2, 3, 5, 7};//分别要乘的数
signed main()
{
    cin >> n;
    h[1] = 1;
    ma[1] = 1;
    while(cnt < n)
    {
        int num, minn = 1e18;   
        for(int i = 1; i <= 4; i++)
        {
            int x = h[p[i]] * a[i];//生成每个值去乘2, 3, 5, 7的结果
            if(x < minn)//取x的最小值
            {
                minn = x, num = i;
            }
        }
        if(! ma[minn])//当前出现了新的数
        {
            ma[minn] = 1;//出现过了
            h[++ cnt] = minn;
        }
        p[num] ++;//指针移动
    } 
    cout << h[n];
    return 0;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;
int n, m;
int a[200 + 9], t[20 + 9];
bool work(int l, int r)
{
    for (int i = 1; i <= m; i ++)
    {
        t[i] = false;
    }
    for (int i = l; i <= r; i ++)
    {
        t[a[i]] ++;
    }
    for (int i = 1; i <= m; i ++)
    {
        if (t[i] == 0)
        {
            return false;
        }
    }
    return true;
}
signed main()
{
    int minn = 1e9, ansi, ansj;
    cin >> n >> m;
    for (int i = 1; i <= n; i ++)
    {
        cin >> a[i];
    }
    for (int i = 1; i <= n - m; i ++)//应该用双指针解
    {
        for (int j = i + m - 1; j <= n; j ++)
        {
            if (work(i, j))
            {
                if (j - i + 1 < minn)
                {
                    minn = j - i + 1;
                    ansi = i;
                    ansj = j;
                }
            }
        }
    }
    cout << ansi << ' ' << ansj; 
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int a[1000000 + 9];
int t[2000 + 9];
int main()
{
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i ++)
    {
        cin >> a[i];
    }
    int l = 1;//左指针为1
    int r = l - 1;//右指针为0
    int st, ed;
    int cnt = 0, minn = 2e9;
    while (r < n)
    {
        while (r < n && cnt < m)//形成一个区间，并且长度要大于当前的数字个数
        {
            r ++;
            t[a[r]] ++;
            if (t[a[r]] == 1)//当前数第一次出现
            {
                cnt ++;//数字种类+1
            }
        }
        while (cnt == m)//恰好相等
        {
            if (r - l + 1 < minn)//计算答案
            {
                st = l;
                ed = r;
                minn = ed - st + 1;
            }
            t[a[l]] --;
            if (t[a[l]] == 0)//当前数没有出现
            {
                cnt --;//数字种类-1
            }
            l ++;
        } 
    }
    cout << st << ' ' << ed << endl;
    return 0;   
}
